import { Link } from '@tanstack/react-router';
import { InvoiceListToolbar } from '../../slots/defs/invoiceListToolbar';
import { useSearchParam, asString } from '../../url/useSearchParam';
import { formatMoney } from '../../ui/money';
import { useInvoices, usePayInvoice, useSendInvoice } from './invoices';

// A project's invoices and what they add up to. Reads its own query key (scoped to the project) and
// derives the total from the rows — the aggregate is never stored, so it always matches the list.
// Each row shows its lifecycle status and the control for its next step: Send while DRAFT, Mark paid
// while SENT (payment is only offered once an invoice has been sent), nothing once PAID. The ordering comes
// from the shared `invoiceSort` URL key (set by a toolbar control), so the server returns the rows
// already in order.
export function InvoiceList({ projectId }: { projectId: number }) {
  const [sort] = useSearchParam('invoiceSort', asString);
  const { data: invoices } = useInvoices(projectId, sort || undefined);
  const send = useSendInvoice(projectId);
  const pay = usePayInvoice(projectId);

  if (!invoices) {
    return null;
  }

  const total = invoices.reduce((sum, invoice) => sum + Number(invoice.amount), 0);

  return (
    <>
    <InvoiceListToolbar.Slot projectId={projectId} />
    <table data-testid="project-invoices-table">
      <thead>
        <tr>
          <th>Amount</th>
          <th>Issued</th>
          <th>Due</th>
          <th>Status</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        {invoices.map((invoice) => (
          <tr key={invoice.id} data-testid={`invoice-row-${invoice.id}`}>
            <td data-testid="invoice-amount">{formatMoney(invoice.amount)}</td>
            <td data-testid="invoice-issued">{invoice.issuedDate}</td>
            <td data-testid="invoice-due">{invoice.dueDate}</td>
            <td data-testid="invoice-status">{invoice.status}</td>
            <td>
              <Link
                to="/invoices/$invoiceId"
                params={{ invoiceId: String(invoice.id) }}
                data-testid={`invoice-open-${invoice.id}`}
              >
                Open
              </Link>
              {invoice.status === 'DRAFT' && (
                <button
                  type="button"
                  data-testid={`invoice-send-${invoice.id}`}
                  disabled={send.isPending}
                  onClick={() => send.mutate({ id: invoice.id })}
                >
                  Send
                </button>
              )}
              {invoice.status === 'SENT' && (
                <button
                  type="button"
                  data-testid={`invoice-pay-${invoice.id}`}
                  disabled={pay.isPending}
                  onClick={() => pay.mutate({ id: invoice.id })}
                >
                  Mark paid
                </button>
              )}
            </td>
          </tr>
        ))}
      </tbody>
      <tfoot>
        <tr>
          <td data-testid="project-invoices-total">{formatMoney(total)}</td>
        </tr>
      </tfoot>
    </table>
    </>
  );
}
===invoices.ts===
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';

// An invoice raised on a project. Everything that shows a project's invoices shares the key
// ['invoices', projectId]; invalidating it after a write refreshes the list and its total together.
export type Invoice = {
  id: number;
  projectId: number;
  amount: number;
  status: string;
  issuedDate: string;
  dueDate: string;
};

export const invoicesKey = (projectId: number) => ['invoices', projectId] as const;

// How a project's invoices are ordered. 'due' asks the server for earliest due date first; any other
// value keeps the default id order. The sort is part of the query key (as a suffix under the shared
// ['invoices', projectId] prefix) so each ordering caches on its own, while a write still invalidates
// the whole prefix and refreshes every ordering at once.
export function useInvoices(projectId: number, sort: string = 'id') {
  return useQuery({
    queryKey: [...invoicesKey(projectId), sort],
    queryFn: () => getJson<Invoice[]>(`/api/invoices?projectId=${projectId}&sort=${sort}`),
  });
}

export function useCreateInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { amount: number }) =>
      postJson<Invoice>('/api/invoices', { projectId, amount: input.amount }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
  });
}

// Send a draft invoice: POSTs {id} and invalidates ['invoices', projectId] so the list reflects the
// new SENT status from the server. Sending is what records the audit entry and unlocks payment.
export function useSendInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { id: number }) =>
      postJson<Invoice>('/api/invoices/send', { id: input.id }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) }),
  });
}

// Mark an invoice paid: POSTs {id} and invalidates ['invoices', projectId] so the list reflects the
// new status from the server. The server also keeps an audit record of every payment.
export function usePayInvoice(projectId: number) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (input: { id: number }) =>
      postJson<Invoice>('/api/invoices/pay', { id: input.id }),
